export class CommerceError extends Error {
  readonly code:
    "validation" | "unavailable" | "conflict" | "forbidden" | "provider";
  constructor(code: CommerceError["code"], message: string) {
    super(message);
    this.name = "CommerceError";
    this.code = code;
  }
}

export function buildOrder(
  input: NewOrderInput,
  products: readonly CommerceProduct[],
  id: string,
  createdAt: string,
): CommerceOrder {
  const result = newOrderSchema.safeParse(input);
  if (!result.success)
    throw new CommerceError("validation", "Check the order fields.");
  const merged = new Map<string, number>();
  for (const line of result.data.items) {
    merged.set(
      line.productId,
      (merged.get(line.productId) ?? 0) + line.quantity,
    );
  }
  let orderCurrency: CommerceCurrency | undefined;
  const items = [...merged].map(([productId, quantity]) => {
    const product = products.find((item) => item.id === productId);
    if (!product || product.status !== "active") {
      throw new CommerceError(
        "unavailable",
        "The selected product is unavailable.",
      );
    }
    if (quantity > 999 || quantity > product.inventory) {
      throw new CommerceError("conflict", "There is not enough inventory.");
    }
    if (orderCurrency && orderCurrency !== product.currency) {
      throw new CommerceError("validation", "Use one currency per order.");
    }
    orderCurrency = product.currency;
    return {
      productId,
      name: product.name,
      quantity,
      unitAmount: product.unitAmount,
      ...(product.images[0] ? { image: product.images[0].src } : {}),
    };
  });
  const order: CommerceOrder = {
    id,
    number: `#${id.replace(/^ord-/, "").slice(0, 12).toUpperCase()}`,
    customerName: result.data.customerName,
    customerEmail: result.data.customerEmail,
    currency: orderCurrency ?? "usd",
    total: items.reduce(
      (sum, item) => sum + item.unitAmount * item.quantity,
      0,
    ),
    status: "processing",
    paymentStatus: "unpaid",
    items,
    createdAt,
    shippingAddress: result.data.shippingAddress ?? "",
  };
  const validated = commerceOrderSchema.safeParse(order);
  if (!validated.success)
    throw new CommerceError("validation", "The order total is out of range.");
  return validated.data;
}

import type { ProductImage } from "@/lib/commerce";

export const MAX_PRODUCT_IMAGES = 6;
export const MAX_PRODUCT_IMAGE_BYTES = 8 * 1024 * 1024;
export const MAX_PRODUCT_IMAGE_EDGE = 900;
export const MAX_PRODUCT_IMAGE_SOURCE_CHARS = 1_000_000;
export const PRODUCT_IMAGE_ACCEPT = "image/png,image/jpeg,image/webp";
const TARGET_SOURCE_CHARS = 220_000;
const MAX_DECODED_EDGE = 8192;
const MAX_DECODED_PIXELS = 24_000_000;

export type ProductImageErrorCode =
  | "unsupported"
  | "empty"
  | "too-large"
  | "signature"
  | "dimensions"
  | "decode"
  | "encode"
  | "unsafe-source"
  | "aborted";

export class ProductImageError extends Error {
  readonly code: ProductImageErrorCode;

  constructor(code: ProductImageErrorCode) {
    super(code);
    this.name = "ProductImageError";
    this.code = code;
  }
}

export type ProductCropAspect =
  "original" | "square" | "portrait" | "landscape";
export type ProductCropSettings = {
  aspect: ProductCropAspect;
  zoom: number;
  rotation: 0 | 90 | 180 | 270;
  offsetX: number;
  offsetY: number;
};

export const defaultProductCrop: ProductCropSettings = {
  aspect: "original",
  zoom: 1,
  rotation: 0,
  offsetX: 0,
  offsetY: 0,
};

export function validateProductImageFile(file: Pick<File, "size" | "type">) {
  if (!["image/png", "image/jpeg", "image/webp"].includes(file.type))
    throw new ProductImageError("unsupported");
  if (!Number.isFinite(file.size) || file.size <= 0)
    throw new ProductImageError("empty");
  if (file.size > MAX_PRODUCT_IMAGE_BYTES)
    throw new ProductImageError("too-large");
}

/** Check the actual container as well as the browser-supplied MIME type. */
export function hasProductRasterSignature(bytes: Uint8Array, mime: string) {
  if (mime === "image/png") {
    return [137, 80, 78, 71, 13, 10, 26, 10].every(
      (byte, index) => bytes[index] === byte,
    );
  }
  if (mime === "image/jpeg")
    return bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  if (mime === "image/webp") {
    return (
      bytes.length >= 12 &&
      [82, 73, 70, 70].every((byte, index) => bytes[index] === byte) &&
      [87, 69, 66, 80].every((byte, index) => bytes[index + 8] === byte)
    );
  }
  return false;
}

export function validateProductRasterDimensions(width: number, height: number) {
  if (
    !Number.isInteger(width) ||
    !Number.isInteger(height) ||
    width < 1 ||
    height < 1 ||
    width > MAX_DECODED_EDGE ||
    height > MAX_DECODED_EDGE ||
    width * height > MAX_DECODED_PIXELS
  ) {
    throw new ProductImageError("dimensions");
  }
}

export function fitProductRaster(
  width: number,
  height: number,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  if (
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width <= 0 ||
    height <= 0 ||
    !Number.isFinite(maxEdge) ||
    maxEdge < 1
  ) {
    throw new ProductImageError("dimensions");
  }
  const edge = Math.min(MAX_PRODUCT_IMAGE_EDGE, Math.floor(maxEdge));
  const scale = Math.min(1, edge / Math.max(width, height));
  return {
    width: Math.max(1, Math.round(width * scale)),
    height: Math.max(1, Math.round(height * scale)),
  };
}

const clamp = (value: number, min: number, max: number, fallback: number) =>
  Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;

/** Coordinates are in the rotated source, before output downsampling. */
export function getProductCropGeometry(
  width: number,
  height: number,
  settings: ProductCropSettings,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  validateProductRasterDimensions(width, height);
  const rotation = [0, 90, 180, 270].includes(settings.rotation)
    ? settings.rotation
    : 0;
  const sideways = rotation === 90 || rotation === 270;
  const rotatedWidth = sideways ? height : width;
  const rotatedHeight = sideways ? width : height;
  const ratio =
    settings.aspect === "square"
      ? 1
      : settings.aspect === "portrait"
        ? 4 / 5
        : settings.aspect === "landscape"
          ? 4 / 3
          : rotatedWidth / rotatedHeight;
  const zoom = clamp(settings.zoom, 1, 3, 1);
  const cropWidth = Math.min(rotatedWidth, rotatedHeight * ratio) / zoom;
  const cropHeight = Math.min(rotatedHeight, rotatedWidth / ratio) / zoom;
  const x =
    ((rotatedWidth - cropWidth) * (clamp(settings.offsetX, -1, 1, 0) + 1)) / 2;
  const y =
    ((rotatedHeight - cropHeight) * (clamp(settings.offsetY, -1, 1, 0) + 1)) /
    2;
  return {
    rotation,
    rotatedWidth,
    rotatedHeight,
    x,
    y,
    cropWidth,
    cropHeight,
    ...fitProductRaster(cropWidth, cropHeight, maxEdge),
  };
}

/** Only prepared local rasters enter a canvas; remote and SVG sources never do. */
export function isEditableProductRaster(src: string) {
  return (
    src.length <= MAX_PRODUCT_IMAGE_SOURCE_CHARS &&
    /^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(src)
  );
}

const builtInCropSources: Readonly<Record<string, string>> = Object.fromEntries(
  [
    "forma-desk-lamp",
    "arc-lounge-chair",
    "linea-notebook",
    "studio-tote",
    "morrow-ceramic-cup",
    "silhouette-vase",
    "fold-side-table",
    "essential-wall-print",
  ].flatMap((slug) => [
    [`/assets/products/${slug}.svg`, `/assets/products/${slug}.webp`],
    [`/assets/products/${slug}.webp`, `/assets/products/${slug}.webp`],
  ]),
);

/** Known demo wrappers crop their original local WebP, never the SVG itself. */
export function canCropProductImage(src: string) {
  return isEditableProductRaster(src) || Object.hasOwn(builtInCropSources, src);
}

export function productImageCropSource(
  src: string,
  assetPath: (path: string) => string,
) {
  if (isEditableProductRaster(src)) return src;
  if (Object.hasOwn(builtInCropSources, src)) {
    return assetPath(builtInCropSources[src]);
  }
  throw new ProductImageError("unsafe-source");
}

/** Read only the embedded raster; arbitrary SVG geometry is never decoded. */
export function extractProductRasterContainer(svg: string) {
  if (svg.length > MAX_PRODUCT_IMAGE_SOURCE_CHARS + 16_384) {
    throw new ProductImageError("too-large");
  }
  const images = [
    ...svg.matchAll(
      /<image\b[^>]*?\s(?:href|xlink:href)=["'](data:image\/(?:webp|png|jpeg);base64,[A-Za-z0-9+/]+={0,2})["'][^>]*>/g,
    ),
  ];
  if (images.length !== 1 || !isEditableProductRaster(images[0][1])) {
    throw new ProductImageError("unsafe-source");
  }
  return images[0][1];
}

export function productImageDisplaySource(
  src: string,
  assetPath: (path: string) => string,
) {
  return src.startsWith("/assets/") ? assetPath(src) : src;
}

export function reorderProductImages(
  images: readonly ProductImage[],
  id: string,
  destination: number,
): ProductImage[] {
  const result = [...images];
  const from = result.findIndex((image) => image.id === id);
  if (
    from < 0 ||
    !Number.isInteger(destination) ||
    destination < 0 ||
    destination >= result.length
  )
    return result;
  const [image] = result.splice(from, 1);
  result.splice(destination, 0, image);
  return result;
}

function checkAborted(signal?: AbortSignal) {
  if (signal?.aborted) throw new ProductImageError("aborted");
}

function loadLocalRaster(src: string, signal?: AbortSignal) {
  checkAborted(signal);
  return new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image();
    let settled = false;
    const cleanup = () => {
      clearTimeout(timeout);
      image.onload = null;
      image.onerror = null;
      signal?.removeEventListener("abort", abort);
    };
    const fail = (error: ProductImageError) => {
      if (settled) return;
      settled = true;
      cleanup();
      image.src = "";
      reject(error);
    };
    const abort = () => fail(new ProductImageError("aborted"));
    const timeout = setTimeout(
      () => fail(new ProductImageError("decode")),
      15_000,
    );
    image.onload = () => {
      if (settled) return;
      try {
        validateProductRasterDimensions(
          image.naturalWidth,
          image.naturalHeight,
        );
        checkAborted(signal);
        settled = true;
        cleanup();
        resolve(image);
      } catch (cause) {
        fail(
          cause instanceof ProductImageError
            ? cause
            : new ProductImageError("decode"),
        );
      }
    };
    image.onerror = () => fail(new ProductImageError("decode"));
    image.decoding = "async";
    signal?.addEventListener("abort", abort, { once: true });
    image.src = src;
  });
}

export function decodeProductRaster(
  src: string,
  signal?: AbortSignal,
  assetPath: (path: string) => string = (path) => path,
) {
  // Text registry installs carry the embedded WebP inside the known SVG.
  // Extract it directly so cropping needs no unshipped binary companion.
  if (Object.hasOwn(builtInCropSources, src) && src.endsWith(".svg")) {
    return (async () => {
      checkAborted(signal);
      let response: Response;
      try {
        response = await fetch(assetPath(src), {
          signal,
          credentials: "same-origin",
          mode: "same-origin",
          redirect: "error",
          cache: "force-cache",
        });
      } catch {
        checkAborted(signal);
        throw new ProductImageError("decode");
      }
      if (!response.ok) throw new ProductImageError("decode");
      const source = extractProductRasterContainer(await response.text());
      checkAborted(signal);
      return loadLocalRaster(source, signal);
    })();
  }
  return loadLocalRaster(productImageCropSource(src, assetPath), signal);
}

export function drawProductRasterCrop(
  canvas: HTMLCanvasElement,
  image: HTMLImageElement,
  settings: ProductCropSettings,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  const geometry = getProductCropGeometry(
    image.naturalWidth,
    image.naturalHeight,
    settings,
    maxEdge,
  );
  canvas.width = geometry.width;
  canvas.height = geometry.height;
  const context = canvas.getContext("2d");
  if (!context) throw new ProductImageError("encode");
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  context.save();
  context.scale(
    geometry.width / geometry.cropWidth,
    geometry.height / geometry.cropHeight,
  );
  context.translate(-geometry.x, -geometry.y);
  context.translate(geometry.rotatedWidth / 2, geometry.rotatedHeight / 2);
  context.rotate((geometry.rotation * Math.PI) / 180);
  context.drawImage(image, -image.naturalWidth / 2, -image.naturalHeight / 2);
  context.restore();
  return geometry;
}

/** Prefer WebP, with the browser's PNG fallback; reduce size before storing. */
export function encodeProductRasterCrop(
  image: HTMLImageElement,
  settings: ProductCropSettings = defaultProductCrop,
): Pick<ProductImage, "src" | "width" | "height"> {
  const canvas = document.createElement("canvas");
  let smallest: Pick<ProductImage, "src" | "width" | "height"> | undefined;
  try {
    for (let pass = 0; pass < 7; pass++) {
      const edge = Math.max(
        180,
        Math.round(MAX_PRODUCT_IMAGE_EDGE * 0.78 ** pass),
      );
      drawProductRasterCrop(canvas, image, settings, edge);
      for (const quality of [0.82, 0.68, 0.54]) {
        const src = canvas.toDataURL("image/webp", quality);
        if (!isEditableProductRaster(src)) continue;
        const result = { src, width: canvas.width, height: canvas.height };
        if (!smallest || src.length < smallest.src.length) smallest = result;
        if (src.length <= TARGET_SOURCE_CHARS) return result;
      }
    }
    if (smallest) return smallest;
    throw new ProductImageError("encode");
  } catch (cause) {
    throw cause instanceof ProductImageError
      ? cause
      : new ProductImageError("encode");
  } finally {
    // Release the canvas backing store after an export, including on failure.
    canvas.width = 0;
    canvas.height = 0;
  }
}

export async function prepareProductImage(
  file: File,
  signal?: AbortSignal,
): Promise<Pick<ProductImage, "src" | "width" | "height">> {
  checkAborted(signal);
  validateProductImageFile(file);
  const signature = new Uint8Array(await file.slice(0, 16).arrayBuffer());
  checkAborted(signal);
  if (!hasProductRasterSignature(signature, file.type))
    throw new ProductImageError("signature");
  const url = URL.createObjectURL(file);
  try {
    const image = await loadLocalRaster(url, signal);
    checkAborted(signal);
    return encodeProductRasterCrop(image);
  } finally {
    URL.revokeObjectURL(url);
  }
}

/**
 * Add the build's mount point to a public asset or native HTML link.
 * Keep next/link and Next's router paths unprefixed: Next handles those itself.
 */
export function publicPath(
  path: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "",
): string {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  const prefix = basePath.trim().replace(/^\/+|\/+$/g, "");
  if (!prefix) return path;
  const base = `/${prefix}`;
  if (
    path === base ||
    path.startsWith(`${base}/`) ||
    path.startsWith(`${base}?`) ||
    path.startsWith(`${base}#`)
  ) {
    return path;
  }
  return `${base}${path}`;
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

/*
 * Aureform effects. Import after the generated tokens.css in globals.css.
 * Component-layer rules allow Tailwind utilities to override decoration.
 * Shadow composition retains Tailwind 4 focus rings.
 */
@layer components {
  .af-surface-gradient {
    background-color: var(--surface);
    background-image: var(--af-gradient-surface);
  }

  .af-hero-gradient {
    background-color: var(--background);
    background-image: var(--af-gradient-hero);
  }

  .af-shadow-soft {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-shadow-elevated {
    --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
  }

  .af-shadow-floating {
    --tw-shadow: var(--af-shadow-floating);
  }

  .af-shadow-soft,
  .af-shadow-elevated,
  .af-shadow-floating,
  .af-hover-card,
  .af-button {
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000);
  }

  .af-button {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-button-primary,
  .af-button-outline,
  .af-button-surface,
  .af-button-destructive {
    background-image: var(--af-gradient-control);
  }

  .af-button-primary,
  .af-button-surface,
  .af-button-destructive {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-hover-card {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      transform var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-hover-link {
    color: var(--primary);
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--primary) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.22em;
    transition:
      color var(--af-motion-fast) var(--af-motion-easing),
      text-decoration-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-hover-link:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    color: var(--primary-hover);
    text-decoration-color: currentColor;
    text-decoration-thickness: 2px;
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  @media (hover: hover) and (pointer: fine) {
    .af-button-outline:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-shadow-soft);
    }

    .af-hover-link:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      color: var(--primary-hover);
      text-decoration-color: currentColor;
      text-decoration-thickness: 2px;
    }
  }

  .af-button:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):active {
    --tw-shadow: 0 0 #0000;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    cursor: default;
    pointer-events: none;
    animation: none;
    transition: none;
    transform: none;
    translate: none;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    --tw-shadow: 0 0 #0000;
    background-image: none;
  }
}

/* Interactive state colors must take precedence over a base bg-surface utility. */
@layer utilities {
  .af-hover-card:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    --tw-shadow: var(--af-shadow-elevated);
    background-color: var(--af-shade-card);
    outline: 2px solid var(--ring);
    outline-offset: 3px;
    transform: translateY(var(--af-motion-lift));
  }

  @media (hover: hover) and (pointer: fine) {
    .af-hover-card:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
      background-color: var(--af-shade-card);
      transform: translateY(var(--af-motion-lift));
    }
  }
}

@layer components {
  .af-appearance-scope {
    color: var(--foreground);
    background-color: var(--background);
    font-family: var(--font-manrope, "Manrope"), system-ui, sans-serif;
  }

  .af-gradient-text {
    color: var(--primary);
    background-image: var(--af-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .af-gradient-border {
    border-color: color-mix(in srgb, var(--primary) 40%, var(--border));
    box-shadow: inset 0 1px 0 color-mix(in srgb, var(--primary) 18%, transparent);
  }

  .af-card {
    --tw-shadow: var(--af-card-shadow, var(--af-shadow-soft));
    background-color: var(--af-card-background, var(--surface));
    background-image: var(--af-card-image, none);
    -webkit-backdrop-filter: var(--af-card-blur, none);
    backdrop-filter: var(--af-card-blur, none);
    border-radius: var(--af-radius, 16px);
    transition:
      border-color var(--af-motion-hover) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      background-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-card-flat {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: 0 0 #0000;
    --af-card-blur: none;
  }
  .af-card-elevated {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
  }
  .af-card-glass {
    --af-card-background: var(--af-glass-background);
    --af-card-image: linear-gradient(130deg, color-mix(in srgb, var(--primary) 8%, transparent), transparent 65%);
    --af-card-shadow: var(--af-shadow-soft);
    --af-card-blur: blur(var(--af-glass-blur));
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }
  .af-card-gradient {
    --af-card-background: var(--surface);
    --af-card-image: linear-gradient(135deg, var(--surface) 25%, color-mix(in srgb, var(--af-color-primary) 20%, var(--surface)));
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }

  .af-control-solid { background-image: none; }
  .af-control-gradient {
    background-color: var(--primary);
    background-image: var(--af-gradient-primary);
    color: var(--primary-foreground);
    --tw-shadow: var(--af-shadow-soft);
  }
  .af-control-gradient:hover:not(:disabled,[data-disabled]) {
    --tw-shadow: var(--af-glow);
  }
  .af-control-soft {
    background-color: var(--accent);
    background-image: none;
    color: var(--accent-foreground);
    border: 1px solid color-mix(in srgb, var(--primary) 24%, var(--border));
  }
  .af-control-outline {
    background-color: var(--surface);
    background-image: none;
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
    --tw-shadow: 0 0 #0000;
  }
  .af-control-glass {
    background-color: var(--af-glass-background);
    background-image: linear-gradient(120deg, color-mix(in srgb, var(--primary) 10%, transparent), transparent);
    backdrop-filter: blur(var(--af-glass-blur));
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
  }

  .af-badge-solid, .af-badge-gradient {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  .af-badge-gradient { background-image: var(--af-gradient-primary); }
  .af-badge-soft { background-color: var(--accent); color: var(--accent-foreground); }
  .af-badge-outline { background-color: transparent; color: var(--foreground); border: 1px solid var(--border); }
  .af-badge-glass { background-color: var(--af-glass-background); color: var(--foreground); border: 1px solid var(--border); backdrop-filter: blur(12px); }

  .af-button-destructive[data-appearance] {
    color: var(--destructive-foreground);
    background-color: var(--destructive);
    background-image: none;
    border-color: color-mix(in srgb, var(--destructive-foreground) 45%, var(--border));
  }
  .af-button[data-disabled], .af-button:disabled {
    background-image: none;
    backdrop-filter: none;
  }

  .af-input, .af-textarea {
    border-color: color-mix(in srgb, var(--muted-foreground) 48%, var(--surface));
  }
}

[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card),
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::before,
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::after {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .af-button,
  .af-button::before,
  .af-button::after,
  .af-button[aria-busy="true"] > svg,
  .af-hover-card,
  .af-hover-card::before,
  .af-hover-card::after,
  .af-hover-link,
  .af-hover-link::before,
  .af-hover-link::after {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    translate: none !important;
  }
}
